import { z } from "zod";
import { coerceUuid } from "./uuid";

/**
 * ForgeState — FlowDesk Durable Session Contracts
 *
 * Every task handoff produces an immutable, verifiable Session Evidence &
 * Fidelity Receipt. These Zod contracts are the single source of truth for
 * selection/state shapes across compiler, verifier, and Composio dispatch.
 */

// ---------------------------------------------------------------------------
// Contract-level resilience helpers
// ---------------------------------------------------------------------------

/**
 * IDs generated by older clients or by sandbox simulations may not be UUIDs.
 * Normalize them deterministically instead of rejecting an otherwise valid
 * capsule/receipt. Genuine UUIDs pass through unchanged.
 */
export const ResilientUuidSchema = z.preprocess(
  coerceUuid,
  z.string().uuid("Expected a UUID"),
);

const ABSOLUTE_URL_RE = /^[a-z][a-z0-9+.-]*:\/\//i;

/**
 * Accept both fully-qualified URLs (`https://example.com`) and the protocol-
 * less links people naturally paste (`www.example.com`, `example.com/path`).
 */
export function normalizeUrl(value: string): string {
  const trimmed = value.trim();
  if (!trimmed) return trimmed;
  if (ABSOLUTE_URL_RE.test(trimmed)) return trimmed;
  return `https://${trimmed.replace(/^\/\//, "")}`;
}

function isValidWebUrl(value: string): boolean {
  try {
    const url = new URL(normalizeUrl(value));
    if (url.protocol !== "http:" && url.protocol !== "https:") return false;
    if (!url.hostname) return false;
    return (
      url.hostname === "localhost" ||
      url.hostname.includes(".") ||
      /^\d{1,3}(?:\.\d{1,3}){3}$/.test(url.hostname)
    );
  } catch {
    return false;
  }
}

/** URL schema that tolerates protocol-less links and normalizes them. */
export const WebUrlSchema = z
  .string()
  .trim()
  .min(1, "URL cannot be empty")
  .transform(normalizeUrl)
  .refine(isValidWebUrl, { message: "Invalid URL" });

/**
 * Replace empty/invalid values with a stable fallback. Useful for LLM output,
 * which frequently emits `""` for optional prose fields.
 */
function resilientString(fallback: string) {
  return z.preprocess((value) => {
    if (typeof value === "string" && value.trim().length > 0) {
      return value.trim();
    }
    if (typeof value === "number" && Number.isFinite(value)) {
      return String(value);
    }
    return fallback;
  }, z.string().min(1));
}

function resilientDuration() {
  return z.preprocess((value) => {
    const numeric = typeof value === "number" ? value : Number(value);
    if (!Number.isFinite(numeric) || numeric <= 0) return 2;
    return Math.max(1, Math.round(numeric));
  }, z.number().int().positive());
}

function resilientDateTime() {
  return z.preprocess((value) => {
    if (typeof value !== "string" || value.trim().length === 0) {
      return undefined;
    }
    const parsed = new Date(value);
    return Number.isNaN(parsed.getTime()) ? undefined : parsed.toISOString();
  }, z.string().datetime().optional());
}

// ---------------------------------------------------------------------------
// Primitive branded types
// ---------------------------------------------------------------------------

export type FilePath = string & { __brand: "FilePath" };
export type LineNumber = number & { __brand: "LineNumber" };
export type URLString = string & { __brand: "URLString" };
export type PersonMention = string & { __brand: "PersonMention" };
export type Deadline = string & { __brand: "Deadline" };
export type Metric = string & { __brand: "Metric" };

// ---------------------------------------------------------------------------
// Extracted hard tokens (deterministic parser output)
// ---------------------------------------------------------------------------

export const ExtractedTokensSchema = z.object({
  file_paths: z.array(z.string().min(1)).default([]),
  line_numbers: z.array(z.number().int().positive()).default([]),
  urls: z.array(WebUrlSchema).default([]),
  dates_deadlines: z.array(z.string().min(1)).default([]),
  people_mentions: z.array(z.string().min(1)).default([]),
  metrics: z.array(z.string().min(1)).default([]),
});

export type ExtractedTokens = z.infer<typeof ExtractedTokensSchema>;

// ---------------------------------------------------------------------------
// Raw input (chaotic brain dump: voice / text / errors / links)
// ---------------------------------------------------------------------------

export const RawInputSchema = z.object({
  text: z.string().min(1, "Raw input cannot be empty"),
  source: z.enum(["text", "voice", "paste"]).default("text"),
  captured_at: z.string().datetime().optional(),
  session_id: z.string().uuid().optional(),
});

export type RawInput = z.infer<typeof RawInputSchema>;

// ---------------------------------------------------------------------------
// Dead-End Firewall entry (what was already tried and failed)
// ---------------------------------------------------------------------------

export const DeadEndEntrySchema = z.object({
  id: resilientString("dead-end"),
  attempt: resilientString("Unknown attempt"),
  error: resilientString("No failure details were provided."),
  tried_at: resilientDateTime(),
});

export type DeadEndEntry = z.infer<typeof DeadEndEntrySchema>;

// ---------------------------------------------------------------------------
// Ordered micro-step (Level 2 / Level 3 checklist)
// ---------------------------------------------------------------------------

export const MicroStepSchema = z.object({
  id: resilientString("step"),
  text: resilientString("Take the next small step."),
  duration_min: resilientDuration(),
  completed: z.preprocess(
    (value) => (typeof value === "boolean" ? value : false),
    z.boolean(),
  ),
});

export type MicroStep = z.infer<typeof MicroStepSchema>;

// ---------------------------------------------------------------------------
// Compiled ForgeState Capsule (the resumption artifact)
// ---------------------------------------------------------------------------

export const ForgeStateCapsuleSchema = z.object({
  capsule_id: ResilientUuidSchema,
  created_at: z.string().datetime(),
  source_input: z.string(),
  source_type: z.enum(["text", "voice", "paste"]),

  // Decompression levels
  one_sentence_summary: z.string().min(1),
  two_minute_anchor: z.string().min(1),
  mental_state: z.string().min(1),

  // Level 2
  dead_ends: z.array(DeadEndEntrySchema).default([]),
  micro_steps: z.array(MicroStepSchema).default([]),

  // Level 3 / technical
  extracted_tokens: ExtractedTokensSchema.default({
    file_paths: [],
    line_numbers: [],
    urls: [],
    dates_deadlines: [],
    people_mentions: [],
    metrics: [],
  }),
  raw_vs_compiled_diff: z.string().optional(),

  // Fidelity evidence
  fidelity_score: z.number().min(0).max(100).default(100),
  intercepted_hallucinations: z.array(z.string()).default([]),
  auto_repaired: z.boolean().default(false),
  receipt_generated: z.boolean().default(false),

  // Composio dispatch targets
  dispatch_targets: z
    .array(z.enum(["github", "slack", "linear", "notion", "url"]))
    .default([]),
});

export type ForgeStateCapsule = z.infer<typeof ForgeStateCapsuleSchema>;
export type ResumptionCapsule = ForgeStateCapsule;

// ---------------------------------------------------------------------------
// Fidelity Receipt (immutable verifiable evidence)
// ---------------------------------------------------------------------------

export const FidelityReceiptSchema = z.object({
  receipt_id: ResilientUuidSchema,
  capsule_id: ResilientUuidSchema,
  generated_at: z.string().datetime(),
  input_length: z.number().int().nonnegative(),
  tokens_extracted: z.number().int().nonnegative(),
  tokens_survived: z.number().int().nonnegative(),
  tokens_lost: z.number().int().nonnegative(),
  hallucinations_intercepted: z.number().int().nonnegative(),
  auto_repairs: z.number().int().nonnegative(),
  /** Pre-repair survival ratio: tokens_survived / tokens_extracted. */
  fidelity_score: z.number().min(0).max(100),
  /** Explicit audit of the initial score, retained even after auto-repair. */
  initial_fidelity_score: z.number().min(0).max(100).optional(),
  /** Post-repair score (100 when the verifier restored every dropped token). */
  final_fidelity_score: z.number().min(0).max(100).optional(),
  repaired: z.boolean().default(false),
  verification_passed: z.boolean(),
  evidence_hash: z.string().min(1),
  /** Indicates the deterministic fallback compiler was used (no LLM verification). */
  deterministic_fallback_used: z.boolean().default(false),
});

export type FidelityReceipt = z.infer<typeof FidelityReceiptSchema>;

// ---------------------------------------------------------------------------
// Composio dispatch request / receipt
// ---------------------------------------------------------------------------

export const ComposioDispatchRequestSchema = z.object({
  capsule_id: ResilientUuidSchema,
  target: z.enum(["github", "slack", "linear", "notion"]),
  payload: z.record(z.string(), z.unknown()),
  sandbox: z.boolean().default(false),
});

export type ComposioDispatchRequest = z.infer<typeof ComposioDispatchRequestSchema>;

export const ComposioDispatchReceiptSchema = z.object({
  request_id: ResilientUuidSchema,
  capsule_id: ResilientUuidSchema,
  target: z.enum(["github", "slack", "linear", "notion"]),
  executed_at: z.string().datetime(),
  sandbox: z.boolean(),
  success: z.boolean(),
  tool_schema: z.string().optional(),
  payload_inspection: z.record(z.string(), z.unknown()).optional(),
  execution_log: z.array(z.string()).default([]),
  receipt_url: z.string().url().optional(),
});

export type ComposioDispatchReceipt = z.infer<typeof ComposioDispatchReceiptSchema>;

// ---------------------------------------------------------------------------
// Validation helpers
// ---------------------------------------------------------------------------

export function validateRawInput(input: unknown): RawInput {
  return RawInputSchema.parse(input);
}

export function validateCapsule(capsule: unknown): ForgeStateCapsule {
  return ForgeStateCapsuleSchema.parse(capsule);
}

export function validateReceipt(receipt: unknown): FidelityReceipt {
  return FidelityReceiptSchema.parse(receipt);
}

export function validateDispatchRequest(req: unknown): ComposioDispatchRequest {
  return ComposioDispatchRequestSchema.parse(req);
}

export function validateDispatchReceipt(receipt: unknown): ComposioDispatchReceipt {
  return ComposioDispatchReceiptSchema.parse(receipt);
}

// ---------------------------------------------------------------------------
// Durable session evidence envelope (immutable audit wrapper)
// ---------------------------------------------------------------------------

export const SessionEvidenceEnvelopeSchema = z.object({
  session_id: ResilientUuidSchema,
  created_at: z.string().datetime(),
  raw_input: RawInputSchema,
  capsule: ForgeStateCapsuleSchema,
  receipt: FidelityReceiptSchema,
  dispatch_receipts: z.array(ComposioDispatchReceiptSchema).default([]),
  verification_passed: z.boolean(),
});

export type SessionEvidenceEnvelope = z.infer<typeof SessionEvidenceEnvelopeSchema>;

export function validateSessionEvidence(envelope: unknown): SessionEvidenceEnvelope {
  return SessionEvidenceEnvelopeSchema.parse(envelope);
}

// ---------------------------------------------------------------------------
// Cognitive Load & Decompression Metrics (for judge evaluation & UI)
// ---------------------------------------------------------------------------

export interface DecompressionMetrics {
  rawWordCount: number;
  compressedWordCount: number;
  cognitiveLoadReductionPct: number;
  extractedEntitiesCount: number;
  compileLatencyMs: number;
  // Before vs After Cognitive Load Metric for judge evaluation
  rawChaosTokenCount: number;      // Total tokens in raw input (lines, symbols, etc.)
  decompressedActionableNodes: number; // Actionable items after compilation
  estimatedResumptionTimeSavedMin: number; // Estimated minutes saved vs manual reconstruction
  hallucinationInterceptionRate: number;   // % of hallucinated tokens intercepted
}

export const DecompressionMetricsSchema = z.object({
  rawWordCount: z.number().int().nonnegative(),
  compressedWordCount: z.number().int().nonnegative(),
  cognitiveLoadReductionPct: z.number().min(0).max(100),
  extractedEntitiesCount: z.number().int().nonnegative(),
  compileLatencyMs: z.number().int().nonnegative(),
  rawChaosTokenCount: z.number().int().nonnegative(),
  decompressedActionableNodes: z.number().int().nonnegative(),
  estimatedResumptionTimeSavedMin: z.number().min(0),
  hallucinationInterceptionRate: z.number().min(0).max(100),
});

export interface CognitiveLevel {
  level: 1 | 2 | 3;
  label: string;
  description: string;
  uiDensity: "minimal" | "balanced" | "full";
}

export const COGNITIVE_LEVELS: CognitiveLevel[] = [
  {
    level: 1,
    label: "Calm",
    description: "Overwhelmed / low working memory — only the #1 next action",
    uiDensity: "minimal",
  },
  {
    level: 2,
    label: "Structured Handoff",
    description: "Balanced focus — mental state, dead ends, ordered micro-steps",
    uiDensity: "balanced",
  },
  {
    level: 3,
    label: "Full Technical Audit",
    description: "Complete context — raw diff, fidelity receipt, Composio dispatch",
    uiDensity: "full",
  },
];

// ---------------------------------------------------------------------------
// Composio Dispatch Types
// ---------------------------------------------------------------------------

export interface ComposioDispatchPayload {
  capsule_id: string;
  target: "github" | "slack" | "linear" | "notion";
  payload: Record<string, unknown>;
  sandbox: boolean;
}

export const ComposioDispatchPayloadSchema = z.object({
  capsule_id: ResilientUuidSchema,
  target: z.enum(["github", "slack", "linear", "notion"]),
  payload: z.record(z.string(), z.unknown()),
  sandbox: z.boolean().default(true),
});

// ---------------------------------------------------------------------------
// Enhanced types for Phase 2 requirements
// ---------------------------------------------------------------------------

export type EnhancedForgeStateCapsule = ForgeStateCapsule & {
  metrics?: DecompressionMetrics;
  tier1?: {
    title: "Calm Next-Step";
    summary: string;
    one_sentence_summary: string;
  };
  tier2?: {
    title: "Structured Tactical Plan";
    anchor: string;
    two_minute_anchor: string;
    mental_state: string;
    dead_ends: DeadEndEntry[];
    micro_steps: MicroStep[];
  };
  tier3?: {
    title: "Full Context & Handoff Capsule";
    extracted_tokens: ExtractedTokens;
    raw_vs_compiled_diff?: string;
    open_blockers?: string[];
    dependency_list?: string[];
  };
};

export type EnhancedFidelityReceipt = FidelityReceipt & {
  grounding_score: number;
  verified_entities: string[];
  ungrounded_entities: string[];
  deterministic_fallback_used: boolean;
  signature: string;
}